module wcd_finder #(\n    parameter MAX_PAIRS = 8,\n    parameter DATA_WIDTH = 32,\n    parameter MAX_CANDIDATES = 8\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [DATA_WIDTH-1:0] a_in,\n    input wire [DATA_WIDTH-1:0] b_in,\n    input wire [2:0] pair_count,\n    output reg [DATA_WIDTH-1:0] wcd_result,\n    output reg done,\n    output reg valid\n);\n\n    // State definitions\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] FACTOR_CHECK = 3'd1;\n    localparam [2:0] FACTOR_UPDATE= 3'd2;\n    localparam [2:0] RESULT_READY = 3'd3;\n    \n    // Internal registers\n    reg [DATA_WIDTH-1:0] candidates [0:MAX_CANDIDATES-1];\n    reg [2:0] state, next_state;\n    reg [2:0] pair_index;\n    reg [2:0] candidate_index;\n    reg [2:0] valid_count;\n    reg [DATA_WIDTH-1:0] stored_a, stored_b;\n    reg [3:0] cycle_counter;\n    localparam [3:0] MAX_CYCLES = 4'd15;\n\n    // Helper wires for divisibility checks\n    wire candidate_divides_a;\n    wire candidate_divides_b;\n    wire is_valid_candidate;\n    \n    assign candidate_divides_a = (stored_a % candidates[candidate_index] == 0);\n    assign candidate_divides_b = (stored_b % candidates[candidate_index] == 0);\n    assign is_valid_candidate = candidate_divides_a || candidate_divides_b;\n\n    integer i;\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            pair_index <= 3'd0;\n            candidate_index <= 3'd0;\n            valid_count <= 3'd0;\n            wcd_result <= {DATA_WIDTH{1'b0}};\n            stored_a <= {DATA_WIDTH{1'b0}};\n            stored_b <= {DATA_WIDTH{1'b0}};\n            cycle_counter <= 4'd0;\n            \n            // Initialize candidates array\n            for (i = 0; i < MAX_CANDIDATES; i = i + 1) begin\n                candidates[i] <= {DATA_WIDTH{1'b0}};\n            end\n        end else begin\n            state <= next_state;\n            cycle_counter <= cycle_counter + 4'd1;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid <= 1'b0;\n                    cycle_counter <= 4'd0;\n                    if (start) begin\n                        pair_index <= 3'd0;\n                        candidate_index <= 3'd0;\n                        valid_count <= 3'd8;  // Assume all initially valid\n                        stored_a <= a_in;\n                        stored_b <= b_in;\n                        // Initialize candidates (fixed prime approach)\n                        for (i = 0; i < MAX_CANDIDATES; i = i + 1) begin\n                            case (i)\n                                3'd0: candidates[i] <= (a_in > 32'd1) ? a_in : 32'd2;\n                                3'd1: candidates[i] <= (b_in > 32'd1) ? b_in : 32'd3;\n                                3'd2: candidates[i] <= 32'd5;\n                                3'd3: candidates[i] <= 32'd7;\n                                3'd4: candidates[i] <= 32'd11;\n                                3'd5: candidates[i] <= 32'd13;\n                                3'd6: candidates[i] <= 32'd17;\n                                3'd7: candidates[i] <= 32'd19;\n                            endcase\n                        end\n                    end\n                end\n                \n                FACTOR_CHECK: begin\n                    if (!is_valid_candidate) begin\n                        candidates[candidate_index] <= 32'd0;\n                        if (valid_count > 3'd0) valid_count <= valid_count - 3'd1;\n                    end\n                    candidate_index <= candidate_index + 3'd1;\n                end\n                \n                FACTOR_UPDATE: begin\n                    stored_a <= a_in;\n                    stored_b <= b_in;\n                    candidate_index <= 3'd0;\n                    pair_index <= pair_index + 3'd1;\n                end\n                \n                RESULT_READY: begin\n                    if (valid_count > 3'd0) begin\n                        // Find first non-zero candidate\n                        valid <= 1'b1;\n                        wcd_result <= candidates[0];  // Simplified for example\n                    end else begin\n                        valid <= 1'b0;\n                    end\n                    done <= 1'b1;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: next_state = (start) ? FACTOR_CHECK : IDLE;\n            \n            FACTOR_CHECK: begin\n                if (cycle_counter >= MAX_CYCLES) begin\n                    next_state = RESULT_READY;\n                end else if (candidate_index == MAX_CANDIDATES-1) begin\n                    next_state = (pair_index < pair_count - 3'd1) ? FACTOR_UPDATE : RESULT_READY;\n                end\n            end\n            \n            FACTOR_UPDATE: next_state = FACTOR_CHECK;\n            \n            RESULT_READY: next_state = IDLE;\n            \n            default: next_state = IDLE;\n        endcase\n    end\n\nendmodule